{
  "task_summary": "Predict whether a taxi trip will have a relatively high tip from pre-ride trip and context information under distribution shift.",
  "feature_id": 3,
  "score": 0.72,
  "rationale": "Time of day is generally and causally related to rider mix, trip purpose, traffic, and tipping behavior, so it should retain moderate predictive value across domains; however, it can also partially encode location- or period-specific demand patterns, making it less stable than core trip features."
}

{
  "task_summary": "Predict whether a taxi trip outcome of interest will occur from pre-trip ride context under distribution shift across environments.",
